//! Pinned TEST-watermarked blue attachment, closed and not confirmed for formal release.
use crate::{engine::RuleResult,model::*,rules::*};
use std::collections::BTreeSet;
pub(crate) const ID:&str="TEST034";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut host=target(Zone::Board,EntityKind::Character,Relation::Any,Range::Anywhere);host.subtype=Some("吸血鬼".into());let mut d=attachment_definition(host);d.attachment.as_mut().unwrap().host_icons.investigation=1;d.abilities.push(crate::import20_contest::hand_ability(ID).unwrap());d}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!definition().abilities.iter().any(|e|same(e,a)){return Err("兽性直觉须保留原吸血鬼宿主或支付2弃自身程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if id==ID&&!same(d,&definition()){return Err("兽性直觉原完整定义不可删改".into());}Ok(())}
pub(crate) fn validate_action(id:&str,a:&Action)->RuleResult<()>{if id!=ID{return Ok(());}let e=match a.kind.as_str(){"play" if a.ability_id.as_deref().is_none_or(|k|k=="attach")=>Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),target_id:a.target_id.clone(),..Action::new("play")},"activate" if a.ability_id.as_deref()==Some(crate::import20_contest::TEST034_HAND)=>Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),..Action::new("activate")},_=>return Err("兽性直觉只能原结附或原手牌行动".into())};if *a!=e{return Err("兽性直觉不可夹带目标、数量或额外支付".into());}Ok(())}
impl Game {
 pub(crate) fn test034_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID&&f.ability_key!=crate::import20_contest::TEST034_HAND{return Ok(());}if f.source.card.definition!=ID{return Err("兽性直觉手牌能力来源不符".into());}self.validate_resource_frame(f)?;if f.ability_key==crate::import20_contest::TEST034_HAND{return self.validate_import20_frame(f);}let s=&f.source;let c=&s.card;
  if f.ability_key!="attach"||f.actor>=self.players.len()||c.controller!=f.actor||c.owner>=self.players.len()||c.face_down||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(c,f)|c<f)||s.region.is_some()||s.source_region_instance.is_some()||s.attachment_host_instance.is_some()||s.play_source.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.chosen_region.is_some()||!f.steps.is_empty()||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked|GuardState::Accepted|GuardState::Cancelled)||self.batch3_physical_cards().any(|live|live.id==c.id)||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=1&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_number(id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,f)|a<f))){return Err("兽性直觉结附须保留原来源、资产支付及空程序".into());}
  let [t]=f.targets.as_slice()else{return Err("兽性直觉须有一个原吸血鬼目标".into());};if !same(&t.spec,&definition().abilities[0].targets[0])||!self.mystic_instance_valid(&t.id)||t.public.instance_id!=t.id||t.public.kind!="character"||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some()||t.region_instance.is_some(){return Err("兽性直觉原宿主绑定被改写".into());}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_test034_state(&self)->RuleResult<()>{for i in &self.stack{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID||f.ability_key==crate::import20_contest::TEST034_HAND){let f=i.frame.as_ref().ok_or("兽性直觉事务缺原帧")?;self.test034_frame(f)?;if i.id!=f.frame_id||i.controller!=f.actor||i.deploy_region.is_some()||i.reveal||f.cursor!=0||i.target!=f.targets.first().map(|t|t.id.clone())||!matches!(f.guard,GuardState::Unchecked){return Err("兽性直觉事务外壳不符".into());}if f.ability_key=="attach"{if i.card.as_ref().is_none_or(|c|c.definition!=ID||!self.pack_a_transaction_matches(f,c)){return Err("兽性直觉事务实际卡与原来源不符".into());}}else if i.card.is_some(){return Err("兽性直觉手牌行动不能携带待进场牌".into());}}}
  for e in &self.effects{match e{Effect::Frame{frame:f}=>self.test034_frame(f)?,Effect::Declare{declaration:d}if d.source.card.definition==ID=>return Err("兽性直觉没有触发声明".into()),_=>{}}}
  if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,..}=>self.test034_frame(f)?,ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID=>return Err("兽性直觉没有触发待选".into()),_=>{}}}Ok(())
 }
}
